#include <bits/stdc++.h>
using namespace std;

int main(){
    int n;
    scanf("%d",&n);
    vector<int> p(n);
    for(int i=0;i<n;i++) scanf("%d",&p[i]);

    vector<pair<int,int>> ops;

    auto do_op = [&](int x, int y){
        ops.push_back({x,y});
        vector<int> np;
        for(int i=n-y;i<n;i++) np.push_back(p[i]);
        for(int i=x;i<n-y;i++) np.push_back(p[i]);
        for(int i=0;i<x;i++) np.push_back(p[i]);
        p = np;
    };

    auto find_val = [&](int val) -> int {
        for(int i=0;i<n;i++) if(p[i]==val) return i;
        return -1;
    };

    // Place elements 1, 2, ..., n-2 into positions 0, 1, ..., n-3
    // After that, the last two must be correct
    for(int t=0; t<n-2; t++){
        int pos = find_val(t+1);
        if(pos == t) continue;

        // Step 1: Move element to position n-1 if not already there
        if(pos != n-1){
            // op(pos+1, n-1-pos): x=pos+1, y=n-1-pos
            // x+y = pos+1+n-1-pos = n, need x+y < n. Doesn't work.
            // op(pos+1, n-2-pos): but this doesn't necessarily help
            // Alternative: op(1, n-1-pos) moves element from pos to pos-1... 
            // Let's just rotate element to last position:
            // op(pos, 1): new = [p[n-1], p[pos..n-2], p[0..pos-1]]
            // Element was at pos, now at pos+1 in new array (it's in middle segment starting at index 1)
            // Actually: suffix=[p[n-1]], middle=[p[pos..n-2]], prefix=[p[0..pos-1]]
            // Hmm, element at pos is first of middle, so index 1. That's not helpful directly.

            // Move to last: use op(1, n-1-pos) if valid
            int y1 = n-1-pos;
            if(y1 > 0 && 1+y1 < n){
                do_op(1, y1);
                pos = find_val(t+1);
            }
            if(pos != n-1 && pos > 0){
                int x2 = pos;
                if(x2 > 0 && 1+x2 < n){
                    do_op(x2, 1);
                    pos = find_val(t+1);
                }
            }
        }
        if(pos == t) continue;
        // Step 2: Move from current pos to target t
        if(pos != t){
            int x = t, y = n - pos;
            if(x > 0 && y > 0 && x+y < n){
                do_op(x, y);
            } else if(t == 0 && pos == n-1){
                do_op(1, 1);
                pos = find_val(t+1);
                if(pos != 0){ int xx=0; /* give up this round, try again */ }
            }
        }
    }

    printf("%d\n",(int)ops.size());
    for(auto&[x,y]:ops) printf("%d %d\n",x,y);
}
